alter table public.login_devices add column if not exists status text not null default 'active' check(status in('active','blocked'));
alter table public.login_devices add column if not exists blocked_at timestamptz;
alter table public.login_devices add column if not exists blocked_by uuid references auth.users(id);
create or replace function public.register_login_device(p_device_key text,p_browser text,p_os text,p_device_type text) returns void language plpgsql security definer set search_path=pg_catalog,public,auth as $$declare sid uuid:=public.current_session_id();uid uuid:=auth.uid();device_hash text:=md5(p_device_key);begin if uid is null or sid is null or not public.is_live_auth_session()then raise exception 'Invalid session' using errcode='42501';end if;if not exists(select 1 from public.profiles where id=uid and lower(role::text)in('admin','staff'))then raise exception 'Account is not authorized' using errcode='42501';end if;if exists(select 1 from public.login_devices where user_id=uid and device_key_hash=device_hash and status='blocked')then delete from auth.sessions where id=sid;raise exception 'This device has been blocked by an administrator' using errcode='42501';end if;insert into public.login_devices(session_id,user_id,device_key_hash,browser,os,device_type,status)values(sid,uid,device_hash,left(coalesce(p_browser,'Unknown browser'),80),left(coalesce(p_os,'Unknown OS'),80),left(coalesce(p_device_type,'Computer'),30),'active')on conflict(session_id)do update set last_active=now(),browser=excluded.browser,os=excluded.os,device_type=excluded.device_type;end$$;
drop function if exists public.list_login_devices();
create function public.list_login_devices() returns table(session_id uuid,device_key_hash text,account_email text,role text,browser text,os text,device_type text,login_at timestamptz,last_active timestamptz,is_current boolean,status text) language sql security definer set search_path=pg_catalog,public,auth as $$select d.session_id,d.device_key_hash,u.email::text,lower(p.role::text),d.browser,d.os,d.device_type,d.login_at,d.last_active,d.session_id=public.current_session_id(),d.status from public.login_devices d join auth.users u on u.id=d.user_id join public.profiles p on p.id=d.user_id where public.is_live_auth_session()and(d.user_id=auth.uid()or public.is_dashboard_admin())order by d.last_active desc$$;
create or replace function public.block_login_device(p_session_id uuid) returns void language plpgsql security definer set search_path=pg_catalog,public,auth as $$declare target_user uuid;target_hash text;begin if not public.is_live_auth_session()or not public.is_dashboard_admin()then raise exception 'Admin only' using errcode='42501';end if;select user_id,device_key_hash into target_user,target_hash from public.login_devices where session_id=p_session_id;if target_user is null then raise exception 'Device not found';end if;update public.login_devices set status='blocked',blocked_at=now(),blocked_by=auth.uid()where user_id=target_user and device_key_hash=target_hash;delete from auth.sessions where id in(select session_id from public.login_devices where user_id=target_user and device_key_hash=target_hash);end$$;
create or replace function public.unblock_login_device(p_session_id uuid) returns void language plpgsql security definer set search_path=pg_catalog,public,auth as $$declare target_user uuid;target_hash text;begin if not public.is_live_auth_session()or not public.is_dashboard_admin()then raise exception 'Admin only' using errcode='42501';end if;select user_id,device_key_hash into target_user,target_hash from public.login_devices where session_id=p_session_id;if target_user is null then raise exception 'Device not found';end if;update public.login_devices set status='active',blocked_at=null,blocked_by=null where user_id=target_user and device_key_hash=target_hash;end$$;
revoke all on function public.block_login_device(uuid),public.unblock_login_device(uuid),public.list_login_devices() from public,anon;
grant execute on function public.block_login_device(uuid),public.unblock_login_device(uuid),public.list_login_devices() to authenticated;
